.cn-json-viewer__codemirror--light[data-v-702b6526] .cm-line ::selection {
	color: white !important;
}
.cn-json-viewer__codemirror--dark[data-v-702b6526] .cm-selectionBackground {
	background: #3390ff !important;
}

