	background: #3390ff !important;
	color: white !important;
}
.cn-json-viewer__codemirror--dark[data-v-702b6526] .cm-content ::selection {
	background: #3390ff !important;
	color: white !important;
}
.cn-json-viewer__format-btn[data-v-702b6526] {
	margin-top: 8px;
}
.cn-json-viewer__error[data-v-702b6526] {
	color: var(--color-error);
	font-size: 14px;
}
